/* Record visualizations: source records are never changed by chart rendering. */
window.RecordViews=(()=>{
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function schedule(days,rows,selected,{tone,typeIcon,summary,filters}){return `<section class="daily-schedule"><div class="section-heading"><h3>每日日程</h3><span>从早到晚 ${icon('arrow-down')}</span></div><div class="schedule-dates chart-scroll">${days.map(day=>`<button data-action="schedule-day" data-day="${day}" aria-pressed="${day===selected}"><small>${new Date(day+'T12:00:00').toLocaleDateString('zh-CN',{weekday:'short'})}</small><strong>${Number(day.slice(8))}</strong></button>`).join('')}</div>${filters}<div class="schedule-heading"><strong>${selected.replaceAll('-',' / ')}</strong><span>${rows.length} 条</span></div><div class="schedule-timeline">${rows.length?rows.map((r,i)=>`<button class="schedule-event" data-action="record-detail" data-id="${e(r.id)}"><time>${e(r.time.slice(11,16))}</time><span class="timeline-marker" data-tone="${tone(r.type)}">${icon(typeIcon(r.type))}</span><span class="event-copy"><strong>${e(r.type)}</strong><small>${e(summary(r))}</small></span>${icon('chevron-right')}</button>`).join(''):'<div class="empty">'+icon('journal')+'这一天还没有这类记录</div>'}</div>${rows.length?'<div class="timeline-end">已记录至 '+rows.at(-1).time.slice(11,16)+'</div>':''}</section>`}
function pattern(days,rows,{tone,typeIcon,summary,expanded=false}){
 const event=r=>new Date(r.time).getHours()*60+new Date(r.time).getMinutes(),height=expanded?720:360,bin=expanded?60:120;
 return `<section class="pattern-card ${expanded?'expanded':'compact-pattern'}"><div class="section-heading"><h3>时间规律</h3><button class="quiet" data-action="pattern-expand" aria-expanded="${expanded}">${expanded?'收起':'展开'}${icon(expanded?'chevron-up':'chevron-down')}</button></div><p class="pattern-note">${expanded?'按发生时刻查看':'每 2 小时汇总 · 点选查看明细'}</p><div class="chart-scroll"><div class="pattern-grid"><div class="pattern-days">${days.map(day=>`<div class="pattern-column"><div class="pattern-lane" style="height:${height}px">${Array.from({length:1440/bin},(_,h)=>{const group=rows.filter(r=>r.type!=='睡眠'&&String(r.time).startsWith(day)&&Math.floor(event(r)/bin)===h);if(!group.length)return '';const r=group[0],position=expanded?event(r):(h+.5)*bin;return `<button class="pattern-event" data-tone="${tone(r.type)}" style="top:${position/1440*100}%" data-action="pattern-group" data-ids="${e(group.map(r=>r.id).join(','))}" aria-label="${e(day+' '+Math.floor(h*bin/60)+':00 '+group.length+'条记录')}">${icon(typeIcon(r.type))}${group.length>1?`<b>${group.length}</b>`:''}</button>`}).join('')}${rows.filter(r=>r.type==='睡眠'&&String(r.time).startsWith(day)).map(r=>{const end=event(r),start=Math.max(0,end-Number(r.duration||0));return `<button class="pattern-sleep" style="top:${start/1440*100}%;height:${Math.max(8,(end-start)/1440*height)}px" data-action="record-detail" data-id="${e(r.id)}" aria-label="${e(day+' 睡眠 '+summary(r))}">${expanded?icon('rest'):''}</button>`}).join('')}</div><button class="pattern-date" data-action="chart-day" data-day="${day}" data-filter="全部">${day.slice(5).replace('-','.')}</button></div>`).join('')}</div><div class="pattern-hours" style="height:${height}px">${Array.from({length:7},(_,i)=>`<span style="top:${i/6*100}%">${i*4}</span>`).join('')}</div></div></div><div class="pattern-legend">${[...new Set(rows.map(r=>r.type))].map(t=>`<span data-tone="${tone(t)}">${icon(typeIcon(t))}${e(t)}</span>`).join('')}</div></section>`;
}

function weight(rows,baby,mode='curve'){
 rows=rows.filter(r=>Number(r.weight??r.amount)>0).sort((a,b)=>String(a.time).localeCompare(String(b.time)));
 const birth=baby.birth?new Date(baby.birth+'T00:00:00').getTime():NaN;const hasBirth=Number.isFinite(birth)&&birth<=Date.now();
 const age=r=>(new Date(r.time).getTime()-birth)/86400000/30.4375;
 const reference=hasBirth?GrowthReference[baby.gender]:null;
 const valid=rows.filter(r=>!hasBirth||age(r)>=0);const maxAge=Math.max(6,...valid.map(r=>hasBirth?age(r):0));const ageEnd=Math.ceil(maxAge/6)*6;
 const useReference=reference&&ageEnd<=24;const table=useReference?reference.filter(r=>r[0]<=ageEnd):[];
 const ymax=Math.ceil(Math.max(10,...valid.map(r=>Number(r.weight??r.amount)),...table.map(r=>r[5]))/2)*2;
 const first=valid.length?new Date(valid[0].time).getTime():Date.now(),last=valid.length?new Date(valid.at(-1).time).getTime():first;
 const x=r=>48+(hasBirth?age(r)/ageEnd:(new Date(r.time).getTime()-first)/Math.max(86400000,last-first))*258;
 const y=v=>440-v/ymax*390;
 const points=valid.map(r=>`${x(r)},${y(Number(r.weight??r.amount))}`).join(' ');
 const series=j=>table.map(r=>`${48+r[0]/ageEnd*258},${y(r[j])}`).join(' ');
 const list=rows.map(r=>`<button class="record-row" data-action="record-detail" data-id="${e(r.id)}"><span>${e(r.time.slice(0,10))}<small>${e(r.time.slice(11,16))}</small></span><strong>${Number(r.weight??r.amount)} kg</strong>${icon('chevron-right')}</button>`).join('');
 return `<section class="growth-page"><div class="section-heading"><h2>体重记录</h2><button class="primary" data-action="quick-edit" data-type="体重">${icon('plus')}添加</button></div><div class="view-tabs">${[['curve','体重曲线'],['list','记录列表']].map(([v,l])=>`<button data-action="weight-view" data-view="${v}" aria-pressed="${mode===v}">${l}</button>`).join('')}</div>${mode==='list'?(list||'<div class="empty">还没有体重记录</div>'):`<div class="growth-plot"><div class="growth-source">${useReference?'WHO 儿童生长标准 · '+(baby.gender==='male'?'男宝':'女宝'):'已记录体重'}</div><p class="growth-unit">体重（kg）${useReference?'<span>参考百分位</span>':''}</p><svg viewBox="0 0 360 485" role="img" aria-label="${hasBirth?'按月龄':'按日期'}显示体重记录及${useReference?'WHO参考线':'实际测量点'}"><g class="growth-grid">${Array.from({length:6},(_,i)=>`<path d="M48 ${y(ymax*i/5)}H306"/><text x="36" y="${y(ymax*i/5)+4}" text-anchor="end">${(ymax*i/5).toFixed(1)}</text>`).join('')}${Array.from({length:7},(_,i)=>`<path d="M${48+i*43} 50V440"/><text x="${48+i*43}" y="464" text-anchor="middle">${hasBirth?(i===0?'出生':ageEnd*i/6+'月'):(i===0&&valid.length?valid[0].time.slice(5,10):i===6&&valid.length?valid.at(-1).time.slice(5,10):'')}</text>`).join('')}</g>${useReference?`<polygon points="${series(1)} ${table.slice().reverse().map(r=>`${48+r[0]/ageEnd*258},${y(r[5])}`).join(' ')}" fill="var(--mint)" opacity=".45"/>${[1,2,3,4,5].map(j=>`<polyline class="reference-curve" points="${series(j)}"/><text class="reference-label" x="312" y="${y(table.at(-1)[j])+4}">${GrowthReference.percentiles[j-1]}%</text>`).join('')}`:''}${valid.length>1?`<polyline points="${points}" fill="none" stroke="var(--accent)" stroke-width="2"/>`:''}${valid.map(r=>`<g role="button" tabindex="0" data-action="record-detail" data-id="${e(r.id)}" aria-label="${e(r.time.slice(0,10))}，${Number(r.weight??r.amount)}千克"><circle cx="${x(r)}" cy="${y(Number(r.weight??r.amount))}" r="16" fill="transparent"/><circle cx="${x(r)}" cy="${y(Number(r.weight??r.amount))}" r="5" fill="var(--surface)" stroke="var(--accent)" stroke-width="3"/></g>`).join('')}</svg>${!rows.length?'<p class="empty">添加一次体重，开始记录变化</p>':''}${useReference?'<details class="growth-info"><summary>参考来源</summary><a href="https://www.who.int/tools/child-growth-standards/standards/weight-for-age" target="_blank" rel="noopener">WHO 年龄别体重标准</a><p>3、15、50、85、97 百分位。月度数据以直线连接，仅作参考，不用于诊断。</p></details>':!hasBirth?'<button class="quiet full" data-action="edit-baby" data-id="'+e(baby.id)+'">补充出生日期，按月龄查看</button>':!reference?'<button class="quiet full" data-action="edit-baby" data-id="'+e(baby.id)+'">补充性别，查看参考曲线</button>':'<p class="foot-note">显示实际记录；参考曲线支持 0–24 月。</p>'}</div><details><summary>查看每次记录（${rows.length}）</summary>${list}</details>`}</section>`;
}
return {schedule,pattern,weight};})();
